import MenuJson from "./menus.json";

export default {
  name: "Navbar",
  data() {
    return {
      menu: MenuJson,
      isLanguage: true,
    };
  },
  created() {},
  methods: {
    clearHistory() {
      this.menu.forEach(element => {
        this.$router.replace(`/${element.title}`); // Replaces current URL in history
      });
    }
  },
};
